import logging
from taf.internal.managedobject import ManagedObject


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ManagedExecutor(ManagedObject):

    def __init__(self, ssh_connection, initialization_commands=None, **kwargs):
        super(ManagedExecutor, self).__init__(**kwargs)
        self._ssh_connection = ssh_connection
        self.add_prerequisite(self._ssh_connection)

        self._ssh_connections = [self._ssh_connection]
        self._initialization_commands = initialization_commands or []

    @property
    def ssh_connection(self):
        return self._ssh_connection

    @property
    def ssh_connections(self):
        return self._ssh_connections

    def start(self, command, use_tty=False):
        return self.ssh_connection.start(command, use_tty=use_tty)

    def execute(self, command):
        return self.ssh_connection.execute(command)

    def _setup(self):
        super(ManagedExecutor, self)._setup()
        self._execute_initialization_commands()

    def _execute_initialization_commands(self):
        for command in self._initialization_commands:
            output = self.ssh_connection.execute(command)
            output = output.decode() if isinstance(output, bytes) else output
            logger.info("initialization command '{}'\noutput:\n{}".format(command, output))


class SshHop(ManagedExecutor):
    pass


class SshForwardableHop(SshHop):

    @property
    def forwardable_ssh_connection(self):
        return self._ssh_connections[-1]


class SshForwardableReverseHop(SshHop):

    def __init__(self,
                 ssh_reverse_forwarding,
                 **kwargs):
        super(SshForwardableReverseHop, self).__init__(**kwargs)
        self._ssh_reverse_forwarding = ssh_reverse_forwarding
        self.add_prerequisite(self._ssh_reverse_forwarding)

    def reverse_forwarding(self, forwarding_port, data_exchange):
        self._ssh_reverse_forwarding.config(
            forwarding_port=forwarding_port, data_exchange=data_exchange)


class ExtraSshdForwardableHop(SshForwardableHop):

    def __init__(self,
                 sshd,
                 new_ssh_connection,
                 **kwargs):
        super(ExtraSshdForwardableHop, self).__init__(**kwargs)
        self._sshd = sshd
        new_ssh_connection.add_prerequisite(self._sshd)
        self.add_prerequisite(new_ssh_connection)
        self._ssh_connections.append(new_ssh_connection)


class LxcSshdForwardableHop(SshForwardableHop):

    def __init__(self,
                 sshd,
                 **kwargs):
        super(LxcSshdForwardableHop, self).__init__(**kwargs)
        self._sshd = sshd
        self._ssh_connection.add_prerequisite(self._sshd)


class ExtraSshdSshReverseHop(SshForwardableReverseHop, ExtraSshdForwardableHop):
    pass


class SshForwardableNetcatReverseHop(SshForwardableHop):

    def __init__(self,
                 netcat_reverse_server,
                 **kwargs):
        super(SshForwardableNetcatReverseHop, self).__init__(**kwargs)
        self._netcat_reverse_server = netcat_reverse_server
        self._netcat_reverse_server.attach_executor(self)
        self.add_prerequisite(self._netcat_reverse_server)
